43	}
44	
45	const queryClient = new QueryClient();
46	
47	const App = () => (
48	  <QueryClientProvider client={queryClient}>
49	    <TooltipProvider>
50	      <Toaster />
51	      <Sonner />
52	      <BrowserRouter>
53	        <AuthProvider>
54	          <Routes>
55	            {/* Public routes */}
56	            <Route path="/" element={<Landing />} />
