69	                <Route path="/reports/:id" element={<AuditReport />} />
70	                <Route path="/agents" element={<AgentHub />} />
71	                <Route path="/agents/:taskId" element={<AgentWorkspace />} />
72	                <Route path="/integrations" element={<Integrations />} />
73	                <Route path="/settings" element={<SettingsPage />} />
74	                <Route path="/pricing" element={<Pricing />} />
75	              </Route>
76	
77	              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
78	              <Route element={<AdminRoute />}>
79	                <Route
80	                  path="/admin"
81	                  element={
82	                    <Suspense fallback={<AdminLoadingSpinner />}>
83	                      <AdminLayout />
