1	import { useState, useEffect, useCallback, useId } from "react";
2	import { useNavigate, useSearchParams } from "react-router-dom";
3	import {
4	  ScanLine,
5	  Info,
6	  AlertCircle,
7	  Loader2,
8	  Globe,
9	} from "lucide-react";
10	import { Card, CardContent } from "@/components/ui/card";
11	import { Button } from "@/components/ui/button";
12	import { Input } from "@/components/ui/input";
13	import { Progress } from "@/components/ui/progress";
14	import {
15	  Select,
16	  SelectContent,
17	  SelectItem,
18	  SelectTrigger,
19	  SelectValue,
20	} from "@/components/ui/select";
21	import { ScanProgressTimeline } from "@/components/shared/ScanProgressTimeline";
22	import { BrowserFrame } from "@/components/shared/BrowserFrame";
23	import { PageTransition } from "@/components/shared/PageTransition";
24	import { CRO_PILLARS, SCAN_STEPS, PAGE_TYPES } from "@/lib/constants";
25	import { useAuth } from "@/contexts/AuthContext";
26	import { useCreateScan } from "@/hooks/use-scans";
27	import { useScan } from "@/hooks/use-scans";
28	import { toast } from "sonner";
29	import type { PageType } from "@/types";
30	import { cn } from "@/lib/utils";
31	
32	/** Basic URL validation — checks structure, not reachability */
33	function isValidUrl(str: string): boolean {
34	  try {
35	    const url = new URL(str.startsWith("http") ? str : `https://${str}`);
36	    return url.protocol === "https:" || url.protocol === "http:";
37	  } catch {
38	    return false;
39	  }
40	}
41	
42	/** Normalize URL: prepend https:// if missing */
43	function normalizeUrl(str: string): string {
44	  const trimmed = str.trim();
45	  if (!trimmed) return trimmed;
46	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
47	  return `https://${trimmed}`;
48	}
49	
50	// ── Map scan status to step index ───────────────────────────────
51	
52	function statusToStep(status: string): number {
53	  switch (status) {
54	    case "pending": return 0;
55	    case "analyzing": return 3;
56	    case "completed": return SCAN_STEPS.length;
57	    case "failed": return -1;
58	    default: return 0;
59	  }
60	}
61	
62	const Scan = () => {
63	  const navigate = useNavigate();
64	  const [searchParams] = useSearchParams();
65	  const [rawUrl, setRawUrl] = useState(searchParams.get("url") || "");
66	  const [pageType, setPageType] = useState<PageType>(
67	    (searchParams.get("type") as PageType) || "landing"
68	  );
69	  const [urlError, setUrlError] = useState<string | null>(null);
70	
71	  // activeScanId drives the polling query
72	  const [activeScanId, setActiveScanId] = useState<string | null>(null);
73	  const [simulatedStep, setSimulatedStep] = useState(-1);
74	
75	  const inputId = useId();
76	  const { profile } = useAuth();
77	  const createScan = useCreateScan();
78	
79	  const scansUsed = profile?.scans_used ?? 0;
80	  const scanLimit = profile?.scan_limit ?? 3;
81	  const scansRemaining = scanLimit - scansUsed;
82	  const atLimit = scansRemaining <= 0;
83	
84	  // Poll the scan row while it's pending/analyzing
85	  const { data: pollingScan } = useScan(activeScanId ?? undefined, {
86	    refetchInterval: activeScanId ? 2000 : false,
87	  });
88	
89	  const isAnalyzing = activeScanId !== null;
90	  const normalizedUrl = normalizeUrl(rawUrl);
91	
92	  const totalSteps = SCAN_STEPS.length;
93	  const currentStep = isAnalyzing
94	    ? pollingScan
95	      ? statusToStep(pollingScan.status)
96	      : simulatedStep
97	    : -1;
98	  const progressPercent = currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
99	
100	  // When polling finds a completed/failed scan, navigate or show error
101	  useEffect(() => {
102	    if (!pollingScan) return;
103	    if (pollingScan.status === "completed") {
104	      setTimeout(() => navigate(`/reports/${pollingScan.id}`), 600);
105	    } else if (pollingScan.status === "failed") {
106	      setActiveScanId(null);
107	      setSimulatedStep(-1);
108	      toast.error("Scan failed. Please try again.", {
109	        action: { label: "Retry", onClick: () => startAnalysis() },
110	      });
111	    }
112	  }, [pollingScan?.status]);
113	
114	  // Simulate step progression while waiting for the edge function
115	  useEffect(() => {
116	    if (!isAnalyzing || !activeScanId) return;
117	    if (pollingScan?.status === "completed" || pollingScan?.status === "failed") return;
118	    if (simulatedStep >= totalSteps - 1) return;
119	
120	    const durations = [900, 1400, 1200, 1100, 1300, 1000, 1600];
121	    const timer = setTimeout(
122	      () => setSimulatedStep((prev) => prev + 1),
123	      durations[simulatedStep] ?? 1200
124	    );
125	    return () => clearTimeout(timer);
126	  }, [isAnalyzing, activeScanId, simulatedStep, pollingScan?.status]);
127	
128	  const startAnalysis = useCallback(() => {
129	    setUrlError(null);
130	    if (!rawUrl.trim()) {
131	      setUrlError("Please enter a URL.");
132	      return;
133	    }
134	    if (!isValidUrl(normalizedUrl)) {
135	      setUrlError("Enter a valid URL like https://example.com/page");
136	      return;
137	    }
138	    if (atLimit) return;
139	
140	    setSimulatedStep(0);
141	
142	    createScan.mutate(
143	      { url: normalizedUrl, page_type: pageType },
144	      {
145	        onSuccess: (scan) => {
146	          setActiveScanId(scan.id);
147	        },
148	        onError: (err: unknown) => {
149	          setSimulatedStep(-1);
150	          const message = err instanceof Error ? err.message : "Failed to start scan";
151	          toast.error(message);
152	        },
153	      }
154	    );
155	  }, [rawUrl, normalizedUrl, pageType, atLimit, createScan]);
156	
157	  const handleSubmit = (e: React.FormEvent) => {
158	    e.preventDefault();
159	    startAnalysis();
160	  };
161	
162	  // ── Analysis Progress View ──────────────────────────────────
163	  if (isAnalyzing) {
164	    let hostname = rawUrl;
165	    try { hostname = new URL(normalizedUrl).hostname; } catch { /* keep raw */ }
166	
167	    const displayStep = Math.max(0, currentStep);
168	
169	    return (
170	      <PageTransition>
171	        <div className="mx-auto max-w-2xl space-y-6">
172	          <div>
173	            <h2 className="text-[28px] font-bold text-foreground">Analyzing your page</h2>
174	            <p className="mt-1 text-sm text-muted-foreground">
175	              Scanning <span className="font-medium text-foreground">{hostname}</span> — this usually takes 20-40 seconds
176	            </p>
177	          </div>
178	
179	          {/* Progress bar */}
180	          <div className="space-y-1.5">
181	            <div className="flex items-center justify-between text-sm">
182	              <span className="text-muted-foreground">
183	                Step {Math.min(displayStep + 1, totalSteps)} of {totalSteps}
184	              </span>
185	              <span className="tabular-nums font-medium text-foreground">{Math.min(progressPercent, 100)}%</span>
186	            </div>
187	            <Progress value={Math.min(progressPercent, 100)} className="h-2" />
188	          </div>
189	
190	          {/* Browser frame */}
191	          <BrowserFrame url={normalizedUrl}>
192	            <div className="relative flex h-52 items-center justify-center bg-gradient-to-br from-slate-50 via-white to-slate-50">
193	              {/* Scanning animation */}
194	              <div className="absolute inset-x-0 top-0 h-1 overflow-hidden">
195	                <div className="h-full w-1/3 animate-[shimmer_1.5s_ease-in-out_infinite] bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
196	              </div>
197	              <div className="text-center">
198	                <Loader2 className="mx-auto mb-3 h-8 w-8 animate-spin text-primary" />
199	                <p className="text-sm font-medium text-muted-foreground">
200	                  {displayStep < totalSteps ? SCAN_STEPS[displayStep]?.label : "Finalizing report"}...
201	                </p>
202	              </div>
203	            </div>
204	          </BrowserFrame>
205	
206	          {/* Timeline */}
207	          <Card className="border-slate-200 shadow-none">
208	            <CardContent className="p-6">
209	              <ScanProgressTimeline steps={SCAN_STEPS} currentStep={displayStep} />
210	            </CardContent>
211	          </Card>
212	        </div>
213	      </PageTransition>
214	    );
215	  }
216	
217	  // ── URL Input Form ──────────────────────────────────────────
218	  return (
219	    <PageTransition>
220	      <div className="mx-auto max-w-2xl space-y-8">
221	        <div className="text-center">
222	          <h2 className="text-[28px] font-bold text-foreground">Analyze your page</h2>
223	          <p className="mt-2 text-muted-foreground">
224	            Enter any URL to get a detailed CRO audit with actionable recommendations
225	          </p>
226	        </div>
227	
228	        {/* URL Input Card */}
229	        <Card className="border-slate-200 shadow-none">
230	          <CardContent className="p-8">
231	            <form onSubmit={handleSubmit} className="space-y-4">
232	              <div>
233	                <label htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-foreground">
234	                  Page URL
235	                </label>
236	                <div className="relative">
237	                  <Globe className="absolute left-4 top-1/2 h-4.5 w-4.5 -translate-y-1/2 text-slate-400" />
238	                  <Input
239	                    id={inputId}
240	                    type="text"
241	                    placeholder="example.com/landing-page"
242	                    value={rawUrl}
243	                    onChange={(e) => { setRawUrl(e.target.value); setUrlError(null); }}
244	                    className={cn(
245	                      "h-14 rounded-xl border-slate-200 bg-white pl-11 pr-5 text-base placeholder:text-slate-400 focus-visible:border-primary focus-visible:ring-primary/20",
246	                      urlError && "border-red-300 focus-visible:border-red-400 focus-visible:ring-red-400/20"
247	                    )}
248	                  />
249	                </div>
250	                {urlError && (
251	                  <p className="mt-1.5 flex items-center gap-1 text-sm text-red-600">
252	                    <AlertCircle className="h-3.5 w-3.5" />
253	                    {urlError}
254	                  </p>
255	                )}
256	              </div>
257	
258	              <div>
259	                <label className="mb-1.5 block text-sm font-medium text-foreground">Page type</label>
260	                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
261	                  <SelectTrigger className="h-12 rounded-xl border-slate-200 bg-white">
262	                    <SelectValue placeholder="Select page type" />
263	                  </SelectTrigger>
264	                  <SelectContent>
265	                    {PAGE_TYPES.map((type) => (
266	                      <SelectItem key={type.value} value={type.value}>
267	                        {type.label}
268	                      </SelectItem>
269	                    ))}
270	                  </SelectContent>
271	                </Select>
272	                <p className="mt-1 text-xs text-muted-foreground">
273	                  Page type affects how we weight each CRO pillar in the overall score
274	                </p>
275	              </div>
276	
277	              <Button
278	                type="submit"
279	                className="h-14 w-full rounded-xl text-base font-semibold"
280	                disabled={!rawUrl.trim() || atLimit || createScan.isPending}
281	              >
282	                {atLimit ? (
283	                  "Scan limit reached — Upgrade to continue"
284	                ) : createScan.isPending ? (
285	                  <>
286	                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
287	                    Starting scan...
288	                  </>
289	                ) : (
290	                  <>
291	                    <ScanLine className="mr-2 h-5 w-5" />
292	                    Start Analysis
293	                  </>
294	                )}
295	              </Button>
296	            </form>
297	
298	            {/* Usage indicator */}
299	            <div className="mt-4 flex items-center justify-center gap-4 text-xs text-muted-foreground">
300	              <span className="flex items-center gap-1">
301	                {atLimit ? (
302	                  <AlertCircle className="h-3.5 w-3.5 text-red-500" />
303	                ) : scansRemaining === 1 ? (
304	                  <AlertCircle className="h-3.5 w-3.5 text-amber-500" />
305	                ) : (
306	                  <Info className="h-3.5 w-3.5" />
307	                )}
308	                {scansUsed}/{scanLimit} scans used this month
309	              </span>
310	              <span>&middot;</span>
311	              <span>~30 seconds per scan</span>
312	            </div>
313	          </CardContent>
314	        </Card>
315	
316	        {/* What we analyze */}
317	        <div>
318	          <h3 className="mb-4 text-center text-xs font-semibold uppercase tracking-widest text-muted-foreground">
319	            7 pillars we analyze
320	          </h3>
321	          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
322	            {CRO_PILLARS.map((pillar) => {
323	              const Icon = pillar.icon;
324	              return (
325	                <Card
326	                  key={pillar.key}
327	                  className="group border-slate-200 shadow-none hover:border-primary/30 hover:shadow-sm transition-all"
328	                >
329	                  <CardContent className="flex flex-col items-center p-4 text-center">
330	                    <div className="mb-2.5 flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 group-hover:bg-primary/15 transition-colors">
331	                      <Icon className="h-4 w-4 text-primary" />
332	                    </div>
333	                    <p className="text-xs font-medium text-foreground leading-tight">
334	                      {pillar.label}
335	                    </p>
336	                    <p className="mt-1 text-[10px] leading-snug text-muted-foreground">
337	                      {Math.round(pillar.weight * 100)}% weight
338	                    </p>
339	                  </CardContent>
340	                </Card>
341	              );
342	            })}
343	          </div>
344	        </div>
345	
346	        {/* How scoring works */}
347	        <Card className="border-slate-200 bg-slate-50/50 shadow-none">
348	          <CardContent className="p-5">
349	            <div className="flex items-start gap-3">
350	              <Info className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" />
351	              <div className="text-xs text-muted-foreground leading-relaxed">
352	                <span className="font-medium text-foreground">How scoring works:</span> Each pillar is scored 0-100 based on specific checks.
353	                Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts.
354	                Your overall score is a weighted average compared against industry benchmarks.
355	              </div>
356	            </div>
357	          </CardContent>
358	        </Card>
359	      </div>
360	    </PageTransition>
361	  );
362	};
363	
364	export default Scan;
