1	import { useEffect, useState } from "react";
2	import { Link, useNavigate } from "react-router-dom";
3	import { Bot, Star } from "lucide-react";
4	import { Button } from "@/components/ui/button";
5	import { Input } from "@/components/ui/input";
6	import { Label } from "@/components/ui/label";
7	import { Separator } from "@/components/ui/separator";
8	import { toast } from "sonner";
9	import { useAuth } from "@/contexts/AuthContext";
10	
11	const Signup = () => {
12	  const navigate = useNavigate();
13	  const { user, signUp, signInWithGoogle, loading } = useAuth();
14	
15	  const [name, setName] = useState("");
16	  const [email, setEmail] = useState("");
17	  const [password, setPassword] = useState("");
18	  const [submitting, setSubmitting] = useState(false);
19	  const [googleLoading, setGoogleLoading] = useState(false);
20	
21	  // Redirect if already authenticated
22	  useEffect(() => {
23	    if (!loading && user) {
24	      navigate("/dashboard", { replace: true });
25	    }
26	  }, [user, loading, navigate]);
27	
28	  const handleSubmit = async (e: React.FormEvent) => {
29	    e.preventDefault();
30	
31	    if (!name.trim()) { toast.error("Name is required."); return; }
32	    if (!email.trim()) { toast.error("Email is required."); return; }
33	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast.error("Enter a valid email address."); return; }
34	    if (!password) { toast.error("Password is required."); return; }
35	    if (password.length < 8) { toast.error("Password must be at least 8 characters."); return; }
36	
37	    setSubmitting(true);
38	    const { error } = await signUp(email, password, name.trim());
39	    setSubmitting(false);
40	
41	    if (error) {
42	      toast.error(error.message ?? "Sign up failed. Please try again.");
43	      return;
44	    }
45	
46	    toast.success("Account created! Check your email to confirm your address.");
47	    navigate("/dashboard", { replace: true });
48	  };
49	
50	  const handleGoogleSignup = async () => {
51	    setGoogleLoading(true);
52	    const { error } = await signInWithGoogle();
53	    if (error) {
54	      toast.error(error.message ?? "Google sign-in failed. Please try again.");
55	      setGoogleLoading(false);
56	    }
57	    // On success the page navigates away via OAuth redirect.
58	  };
59	
60	  return (
61	    <div className="flex min-h-screen">
62	      {/* Left — Form */}
63	      <div className="flex flex-1 flex-col justify-center px-8 py-12 sm:px-16 lg:px-24">
64	        <div className="mx-auto w-full max-w-sm">
65	          {/* Logo */}
66	          <Link to="/" className="mb-10 flex items-center gap-2">
67	            <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
68	              <Bot className="h-4 w-4 text-white" />
69	            </div>
70	            <span className="text-lg font-bold tracking-tight text-foreground">CROBOT</span>
71	          </Link>
72	
73	          <h1 className="text-2xl font-bold text-foreground">Create your account</h1>
74	          <p className="mt-1.5 text-sm text-muted-foreground">
75	            Start improving your conversions today
76	          </p>
77	
78	          {/* Google sign-up */}
79	          <Button
80	            variant="outline"
81	            className="mt-8 w-full border-slate-200 py-5"
82	            onClick={handleGoogleSignup}
83	            disabled={googleLoading || submitting}
84	          >
85	            {googleLoading ? (
86	              <span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-muted-foreground border-t-transparent" />
87	            ) : (
